@layer material, material-high-contrast, size;

:is(:root, :host) {
	--db-focus-outline-color: light-dark(#257fa8, #257fa8);
	--db-divider-bg-color: var(--db-border-decorative);
	--db-backdrop-color-weak: color-mix(
		in srgb,
		light-dark(#16181b, #edeef0) 32%,
		transparent
	);
	--db-backdrop-color-strong: color-mix(
		in srgb,
		light-dark(#16181b, #edeef0) 68%,
		transparent
	);
	--db-indicator-color: light-dark(#ef0016, #ef0016);
	--db-indicator-background: linear-gradient(
		135deg,
		var(--db-pride-red, var(--db-indicator-color)) 16.7%,
		var(--db-pride-orange, var(--db-indicator-color)) 0,
		var(--db-pride-orange, var(--db-indicator-color)) 33.4%,
		var(--db-pride-yellow, var(--db-indicator-color)) 0,
		var(--db-pride-yellow, var(--db-indicator-color)) 50.1%,
		var(--db-pride-green, var(--db-indicator-color)) 0,
		var(--db-pride-green, var(--db-indicator-color)) 66.8%,
		var(--db-pride-blue, var(--db-indicator-color)) 0,
		var(--db-pride-blue, var(--db-indicator-color)) 83.5%,
		var(--db-pride-violet, var(--db-indicator-color)) 0
	);
	--db-font-weight: normal;
	--db-opacity-disabled: 0.4;
	--db-opacity-emphasis-low: 0.75;
}

:root,
:host {
	background-color: var(--db-bg-default);
	color: var(--db-text-default);
}

[data-pride="true"] {
	--db-pride-red: light-dark(#ec0016, #ec0016);
	--db-pride-orange: light-dark(#f69400, #f69400);
	--db-pride-yellow: light-dark(#ffd800, #ffd800);
	--db-pride-green: light-dark(#408335, #408335);
	--db-pride-blue: light-dark(#1455c0, #1455c0);
	--db-pride-violet: light-dark(#814997, #814997);
}

:where(ul) li::marker {
	color: var(--db-indicator-color);
}

html {
	-webkit-tap-highlight-color: color-mix(
		in srgb,
		light-dark(#1b6586, #2e9acb) 8%,
		transparent
	);
}

